const data = $input.first().json;

let text =
  data.output?.[0]?.content?.find(item => item.type === 'output_text')?.text;

if (!text) {
  throw new Error('No AI JSON text found');
}

text = text
  .trim()
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/, '');

const result = JSON.parse(text);

// Normalize Quote Readiness status
const originalStatus = String(
  result.quote_readiness?.status ?? ''
).trim();

const status = originalStatus.toLowerCase();

let normalizedStatus;

if (
  status.startsWith('q0') ||
  status.includes('insufficient')
) {
  normalizedStatus = 'Q0';
} else if (
  status.startsWith('q1') ||
  status.includes('clarification')
) {
  normalizedStatus = 'Q1';
} else if (
  status.startsWith('q2') ||
  status.includes('internal review')
) {
  normalizedStatus = 'Q2';
} else if (
  status.startsWith('q3') ||
  status.includes('ready to quote')
) {
  normalizedStatus = 'Q3';
} else {
  throw new Error(
    `Unknown quote readiness status: ${originalStatus}`
  );
}

// Preserve AI's original wording for reference
result.quote_readiness.status_label = originalStatus;

// Give downstream workflow one stable value
result.quote_readiness.status = normalizedStatus;

return [
  {
    json: result
  }
];

